    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def KDistanceNodes(root, target, k):
    def build_graph(node, parent=None):
        if node is None:
            return
        if parent:
            graph[node] = [parent]
        else:
            graph[node] = []
        if node.left:
            graph[node].append(node.left)
            build_graph(node.left, node)
        if node.right:
            graph[node].append(node.right)
            build_graph(node.right, node)

    def dfs(node, distance, visited):
        if node in visited:
            return
        visited.add(node)
        if distance == k:
            result.append(node.val)
            return
        for neighbor in graph[node]:
            dfs(neighbor, distance + 1, visited)

    graph = {}
    build_graph(root)
    result = []
    target_node = None
    queue = [root]
    while queue:
        current = queue.pop(0)
        if current.val == target:
            target_node = current
            break
        if current.left:
            queue.append(current.left)
        if current.right:
            queue.append(current.right)

    dfs(target_node, 0, set())
    return sorted(result)
